package net.civeira.phylax.features.document.theme.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class IsDefaultVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property is default of theme ")
  void test_is_default_v_o_builder() {
    Assertions.assertFalse(IsDefaultVO.nullValue().isIsDefault(),
        "A empty vo should have a null value");
    Assertions.assertFalse(IsDefaultVO.tryFrom(null).isIsDefault(),
        "With a null value, no present result");
    Assertions.assertEquals(true, IsDefaultVO.from(true).isIsDefault());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> IsDefaultVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", IsDefaultVO.from(true).toString());
  }
}
